                is DataState.Success -> {
                    hideLoading()
                    reportApiCall(true)

                    job.status = ConnectJobRecord.STATUS_LEARNING
                    ConnectJobUtils.upsertJob(job)

                    if (!hasLiveView()) return@observe
                    hideError()

                    launchApp(isLearning = true)
